        if grid[r][0] != bg and all(v == grid[r][0] for v in grid[r]):
            line = ("h", r, grid[r][0])
            break
    if line is None:
        for c in range(w):
            if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
                line = ("v", c, grid[0][c])
                break
    if line is None:
        return out

    orient, pos, linecolor = line
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != linecolor]
    if not cells:
        return out
    color = grid[cells[0][0]][cells[0][1]]

    if orient == "h":
        rs = [r for r, c in cells]
        top, bottom = min(rs), max(rs)
        # Slide object to sit adjacent to the line.
        delta = (pos + 1 - top) if top > pos else (pos - 1 - bottom)
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + delta][c] = color
        stripe = top - 1 if top > pos else bottom + 1
        if abs(delta) > 0 and 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        cs = [c for r, c in cells]
        left, right = min(cs), max(cs)
        # If already adjacent, mark just beyond the object's far edge.
        if abs(left - pos) == 1 or abs(right - pos) == 1:
            stripe = right + 1 if left > pos else left - 1
            if 0 <= stripe < w:
                for r in range(h):
                    out[r][stripe] = 8
